#include <stdio.h>
#include <pthread.h>

// Thread function – prints numbers 1..5
void* print_numbers(void *arg) {
    int id = *(int*)arg; // thread id passed via argument
    for(int i=1;i<=5;i++) {
        printf("Thread %d: %d
", id, i);
    }
    return NULL; // thread terminates here
}

int main(){
    pthread_t t1, t2;
    int id1=1, id2=2;
    // Create two threads
    pthread_create(&t1, NULL, print_numbers, &id1); // New → Ready
    pthread_create(&t2, NULL, print_numbers, &id2);
    // Wait for both threads to finish (join)
    pthread_join(t1, NULL); // moves to Terminated after return
    pthread_join(t2, NULL);
    return 0;
}
// Important: each thread has its own stack; main joins to avoid resource leak.

