#include <stdio.h>
#include <stdlib.h>

typedef enum {
    NEW,
    READY,
    RUNNING,
    WAITING,
    TERMINATED
} State;

const char* getStateName(State s) {
    switch (s) {
        case NEW: return "NEW";
        case READY: return "READY";
        case RUNNING: return "RUNNING";
        case WAITING: return "WAITING";
        case TERMINATED: return "TERMINATED";
    }
    return "UNKNOWN";
}

int main() {
    State current = NEW;
    printf("Initial State: %s\n", getStateName(current));

    current = READY; // Admitted
    printf("Transition to: %s\n", getStateName(current));

    current = RUNNING; // Dispatched
    printf("Transition to: %s\n", getStateName(current));

    current = WAITING; // I/O Request
    printf("Transition to: %s\n", getStateName(current));

    current = READY; // I/O Complete
    printf("Transition to: %s\n", getStateName(current));

    current = RUNNING; // Scheduled again
    printf("Transition to: %s\n", getStateName(current));

    current = TERMINATED; // Exit
    printf("Transition to: %s\n", getStateName(current));
    return 0;
}

