#include <stdio.h>
#include <string.h>

typedef struct {
    int pid;
    int pc;
    int reg_a;
} CPUContext;

void save_context(CPUContext *cpu, CPUContext *pcb) {
    pcb->pid = cpu->pid;
    pcb->pc = cpu->pc;
    pcb->reg_a = cpu->reg_a;
}

void load_context(CPUContext *pcb, CPUContext *cpu) {
    cpu->pid = pcb->pid;
    cpu->pc = pcb->pc;
    cpu->reg_a = pcb->reg_a;
}

int main() {
    CPUContext cpu = {0, 0, 0};

    CPUContext pcbA = {101, 505, 42};
    CPUContext pcbB = {102, 902, 99};

    // Load Process A onto CPU
    load_context(&pcbA, &cpu);
    printf("Running PID %d at PC %d with RegA %d\n", cpu.pid, cpu.pc, cpu.reg_a);

    // Context switch: Save A, Load B
    save_context(&cpu, &pcbA);
    load_context(&pcbB, &cpu);

    printf("--- AFTER CONTEXT SWITCH ---\n");
    printf("Running PID %d at PC %d with RegA %d\n", cpu.pid, cpu.pc, cpu.reg_a);
    return 0;
}

