#include <stdio.h>

// Simplified Non-Preemptive SJF Implementation
void computeSJF(int p[], int bt[], int n) {
    // Sort processes by burst time (Bubble Sort for simplicity)
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (bt[i] > bt[j]) {
                int temp = bt[i]; bt[i] = bt[j]; bt[j] = temp;
                temp = p[i]; p[i] = p[j]; p[j] = temp;
            }
        }
    }

    int wt = 0, total_wt = 0;
    printf("Process\tBurst\tWaiting\n");
    for (int i = 0; i < n; i++) {
        printf("P%d\t\t%d\t%d\n", p[i], bt[i], wt);
        total_wt += wt;
        wt += bt[i];
    }
    printf("Average Waiting Time: %.2f\n", (float)total_wt / n);
}

int main() {
    int processes[] = {1, 2, 3};
    int burst_time[] = {6, 2, 8};
    computeSJF(processes, burst_time, 3);
    return 0;
