#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int pid;          // process id
    int arrival;      // arrival time
    int burst;        // total CPU burst
    int remaining;    // remaining time
    int finish;       // completion time
} Process;

// comparator for qsort: smallest remaining time first
int cmp(const void *a, const void *b) {
    Process *p1 = (Process *)a;
    Process *p2 = (Process *)b;
    if (p1->remaining != p2->remaining)
        return p1->remaining - p2->remaining;
    return p1->arrival - p2->arrival; // tie‑breaker
}

int main() {
    Process proc[] = {
        {1, 0, 8, 8, 0},
        {2, 1, 4, 4, 0},
        {3, 2, 9, 9, 0},
        {4, 3, 5, 5, 0}
    };
    int n = sizeof(proc) / sizeof(proc[0]);
    int time = 0, completed = 0;
    while (completed < n) {
        // collect ready processes
        int ready = 0;
        Process *readyList = malloc(n * sizeof(Process));
        for (int i = 0; i < n; ++i) {
            if (proc[i].arrival <= time && proc[i].remaining > 0) {
                readyList[ready++] = proc[i];
            }
        }
        if (ready == 0) { // CPU idle
            time++; free(readyList); continue;
        }
        // pick shortest remaining time
        qsort(readyList, ready, sizeof(Process), cmp);
        int idx = -1;
        for (int i = 0; i < n; ++i) {
            if (proc[i].pid == readyList[0].pid) { idx = i; break; }
        }
        // run for 1 unit (pre‑emptive step)
        proc[idx].remaining--;
        time++;
        if (proc[idx].remaining == 0) {
            proc[idx].finish = time;
            completed++;
        }
        free(readyList);
    }
    // display results
    printf("PID\tArrival\tBurst\tFinish\tWaiting\n");
    for (int i = 0; i < n; ++i) {
        int waiting = proc[i].finish - proc[i].arrival - proc[i].burst;
        printf("%d\t%d\t\t%d\t%d\t%d\n", proc[i].pid, proc[i].arrival, proc[i].burst, proc[i].finish, waiting);
    }
    return 0;
}

#include <stdio.h>

// Round Robin Scheduling Simulation in C
void findWaitingTime(int processes[], int n, int bt[], int wt[], int quantum) {
    int rem_bt[n];
    for (int i = 0; i < n; i++) rem_bt[i] = bt[i];
    int t = 0; // Current time
    while (1) {
        int done = 1;
        for (int i = 0; i < n; i++) {
            if (rem_bt[i] > 0) {
                done = 0; // There is a pending process
                if (rem_bt[i] > quantum) {
                    t += quantum;
                    rem_bt[i] -= quantum;
                } else {
                    t = t + rem_bt[i];
                    wt[i] = t - bt[i];
                    rem_bt[i] = 0;
                }
            }
        }
        if (done == 1) break;
    }
}

int main() {
    int processes[] = {1, 2, 3};
    int n = sizeof(processes) / sizeof(processes[0]);
    int burst_time[] = {10, 5, 8};
    int quantum = 2;
    int wt[n], tat[n], total_wt = 0, total_tat = 0;
    findWaitingTime(processes, n, burst_time, wt, quantum);
    for (int i = 0; i < n; i++) total_wt += wt[i];
    printf("Average waiting time = %.2f\n", (float)total_wt / (float)n);
    return 0;
}

#include <stdio.h>

// Priority Scheduling Simulation (Non-Preemptive) in C
struct Process {
    int id, bt, priority, wt, tat;
};

void sortProcesses(struct Process p[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (p[i].priority > p[j].priority) {
                struct Process temp = p[i];
                p[i] = p[j];
                p[j] = temp;
            }
        }
    }
}

int main() {
    struct Process p[] = {{1, 10, 2, 0, 0}, {2, 5, 0, 0, 0}, {3, 8, 1, 0, 0}};
    int n = 3;
    sortProcesses(p, n); // Sort by priority (lower number = higher priority)
    p[0].wt = 0;
    p[0].tat = p[0].bt;
    for (int i = 1; i < n; i++) {
        p[i].wt = p[i - 1].wt + p[i - 1].bt;
        p[i].tat = p[i].wt + p[i].bt;
    }
    printf("Process %d completed with TAT = %d\n", p[0].id, p[0].tat);
    return 0;
}

