typedef struct {
    long long value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} EventCounter;

void init_ec(EventCounter *ec) {
    ec->value = 0;
    pthread_mutex_init(&ec->mutex, NULL);
    pthread_cond_init(&ec->cond, NULL);
}

void advance_ec(EventCounter *ec) {
    pthread_mutex_lock(&ec->mutex);
    ec->value++; // Counter always moves forward
    pthread_cond_broadcast(&ec->cond);
    pthread_mutex_unlock(&ec->mutex);
}

void await_ec(EventCounter *ec, long long v) {
    pthread_mutex_lock(&ec->mutex);
    while (ec->value < v) {
        pthread_cond_wait(&ec->cond, &ec->mutex); // Suspend until target value reached
    }
    pthread_mutex_unlock(&ec->mutex);
}

int main() {
