/* Banker's Algorithm demo – single resource type for clarity */
#include <stdio.h>
#define N 3   // number of processes
#define M 1   // number of resource types

int available[M] = {3};                 // total free units
int max[N][M] = {{7},{5},{3}};          // maximum demand of each process
int allocation[N][M] = {{0},{2},{3}};  // currently allocated units
int need[N][M];                         // will be computed as max - allocation

void calculate_need(){
    for(int i=0;i<N;i++)
        for(int j=0;j<M;j++)
            need[i][j] = max[i][j] - allocation[i][j];
}

int is_safe(){
    int work[M];
    int finish[N] = {0};
    for(int j=0;j<M;j++) work[j] = available[j];
    // try to find a safe sequence
    for(int count=0; count<N; ++count){
        int found = 0;
        for(int i=0;i<N;i++) if(!finish[i]){
            int can_finish = 1;
            for(int j=0;j<M;j++) if(need[i][j] > work[j]) can_finish = 0;
            if(can_finish){
                for(int j=0;j<M;j++) work[j] += allocation[i][j];
                finish[i] = 1; found = 1; break;
            }
        }
        if(!found) return 0; // unsafe
    }
    return 1; // safe
}

int main(){
    calculate_need();
    printf("System is %s\n", is_safe()?"SAFE":"UNSAFE");
    return 0;
}

