#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

pthread_mutex_t mutex;
sem_t wrt;
int read_count = 0;
int data = 0;

void* reader(void* arg) {
    int id = *((int*)arg);
    pthread_mutex_lock(&mutex);
    read_count++;
    if (read_count == 1) {
        sem_wait(&wrt); // First reader locks writer out
    }
    pthread_mutex_unlock(&mutex);

    // Reading section
    printf("Reader %d: read data = %d\n", id, data);
    usleep(100000);

    pthread_mutex_lock(&mutex);
    read_count--;
    if (read_count == 0) {
        sem_post(&wrt); // Last reader releases writer
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* writer(void* arg) {
    int id = *((int*)arg);
    sem_wait(&wrt); // Exclusive write access

    // Writing section
    data++;
    printf("Writer %d: wrote data = %d\n", id, data);
    usleep(100000);

    sem_post(&wrt);
    return NULL;
}

int main() {
    pthread_t r[5], w[2];
    pthread_mutex_init(&mutex, NULL);
    sem_init(&wrt, 0, 1);
    int ids[5] = {1, 2, 3, 4, 5};

    for(int i=0; i<2; i++) pthread_create(&w[i], NULL, writer, &ids[i]);
    for(int i=0; i<5; i++) pthread_create(&r[i], NULL, reader, &ids[i]);

    for(int i=0; i<2; i++) pthread_join(w[i], NULL);
    for(int i=0; i<5; i++) pthread_join(r[i], NULL);

    pthread_mutex_destroy(&mutex);
    sem_destroy(&wrt);
    return 0;
}

