#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#def_ine N 5
sem_t forks[N];

void* philosopher(void* num) {
    int id = *(int*)num;
    int left = id;
    int right = (id + 1) % N;

    // Asymmetric solution to prevent deadlock:
    // Even philosophers pick left then right; odd pick right then left
    if (id % 2 == 0) {
        sem_wait(&forks[left]);
        sem_wait(&forks[right]);
    } else {
        sem_wait(&forks[right]);
        sem_wait(&forks[left]);
    }

    printf("Philosopher %d is eating\n", id);
    usleep(100000);

    sem_post(&forks[left]);
    sem_post(&forks[right]);
    printf("Philosopher %d is thinking\n", id);
    return NULL;
}

int main() {
    pthread_t thread[N];
    int ids[N];
    for(int i=0; i<N; i++) sem_init(&forks[i], 0, 1);
    for(int i=0; i<N; i++) {
        ids[i] = i;
        pthread_create(&thread[i], NULL, philosopher, &ids[i]);
    }
    for(int i=0; i<N; i++) pthread_join(thread[i], NULL);
    for(int i=0; i<N; i++) sem_destroy(&forks[i]);
    return 0;
}

