/* Simple simulation of variable partitioning using first‑fit */
#include <stdio.h>
#include <stdlib.h>

typedef struct Hole {
    int start;   // start address (simulated)
    int size;    // size of free block
    struct Hole *next;
} Hole;

Hole *freeList = NULL; // head of free‑list

void init(int total) {
    freeList = malloc(sizeof(Hole));
    freeList->start = 0;
    freeList->size = total;
    freeList->next = NULL;
}

// allocate size bytes, return start address or -1 if fail
int allocate(int sz) {
    Hole *prev = NULL, *cur = freeList;
    while (cur) {
        if (cur->size >= sz) {               // first‑fit condition
            int addr = cur->start;
            cur->start += sz;                // shrink hole
            cur->size -= sz;
            if (cur->size == 0) {            // hole exhausted, remove it
                if (prev) prev->next = cur->next;
                else freeList = cur->next;
                free(cur);
            }
            return addr;                     // allocated address
        }
        prev = cur;
        cur = cur->next;
    }
    return -1; // no suitable hole
}

void freeBlock(int addr, int sz) {
    // simple insertion at front; real implementation would merge neighbours
    Hole *h = malloc(sizeof(Hole));
    h->start = addr; h->size = sz; h->next = freeList; freeList = h;
}

int main() {
    init(1000);               // total memory = 1000 units
    int a = allocate(200);    // allocate 200 -> address 0
    int b = allocate(300);    // allocate 300 -> address 200
    printf("a=%d b=%d\n", a, b);
    freeBlock(a, 200);        // free first block
    int c = allocate(150);    // should reuse freed space, address 0
    printf("c=%d\n", c);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

#define P 5
#define R 3

void calculateNeed(int need[P][R], int max[P][R], int allot[P][R]) {
    for (int i = 0; i < P; i++)
        for (int j = 0; j < R; j++)
            need[i][j] = max[i][j] - allot[i][j];
}

bool isSafe(int processes[], int avail[], int max[P][R], int allot[P][R]) {
    int need[P][R];
    calculateNeed(need, max, allot);

    bool finish[P] = {0};
    int safeSeq[P];
    int work[R];
    for (int i = 0; i < R; i++) work[i] = avail[i];

    int count = 0;
    while (count < P) {
        bool found = false;
        for (int p = 0; p < P; p++) {
            if (finish[p] == 0) {
                int j;
                for (j = 0; j < R; j++)
                    if (need[p][j] > work[j])
                        break;
                if (j == R) {
                    for (int k = 0; k < R; k++)
                        work[k] += allot[p][k];
                    safeSeq[count++] = p;
                    finish[p] = 1;
                    found = true;
                }
            }
        }
        if (found == false) {
            printf("System is not in a safe state.\n");
            return false;
        }
    }
    printf("System is in a safe state. Safe sequence is: ");
    for (int i = 0; i < P; i++) printf("P%d ", safeSeq[i]);
    printf("\n");
    return true;
}

int main() {
    int processes[] = {0, 1, 2, 3, 4};
    int avail[] = {3, 3, 2};
    int max[P][R] = {{7, 5, 3}, {3, 2, 2}, {9, 0, 2}, {2, 2, 2}, {4, 3, 3}};
    int allot[P][R] = {{0, 1, 0}, {2, 0, 0}, {3, 0, 2}, {2, 1, 1}, {0, 0, 2}};
    isSafe(processes, avail, max, allot);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

#define NUM_PROC 3
#define NUM_RES 3

// Simplified detection check for multi-instance resources
bool detectDeadlock(int avail[], int alloc[][NUM_RES], int req[][NUM_RES]) {
    int work[NUM_RES];
    bool finish[NUM_PROC];

    for (int i = 0; i < NUM_RES; i++) work[i] = avail[i];
    for (int i = 0; i < NUM_PROC; i++) {
        if (alloc[i][0] == 0 && alloc[i][1] == 0 && alloc[i][2] == 0)
            finish[i] = true; // Process not holding any resources
        else
            finish[i] = false;
    }

    bool changed;
    do {
        changed = false;
        for (int i = 0; i < NUM_PROC; i++) {
            if (!finish[i]) {
                int j;
                for (j = 0; j < NUM_RES; j++)
                    if (req[i][j] > work[j]) break;
                if (j == NUM_RES) {
                    for (int k = 0; k < NUM_RES; k++)
                        work[k] += alloc[i][k];
                    finish[i] = true;
                    changed = true;
                }
            }
        }
    } while (changed);

    for (int i = 0; i < NUM_PROC; i++) {
        if (!finish[i]) return true; // Deadlock detected!
    }
    return false;
}

int main() {
    int avail[] = {0, 0, 0};
    int alloc[NUM_PROC][NUM_RES] = {{0, 1, 0}, {2, 0, 0}, {3, 0, 3}};
    int req[NUM_PROC][NUM_RES] = {{0, 0, 0}, {2, 0, 2}, {0, 0, 0}};

    if (detectDeadlock(avail, alloc, req))
        printf("Deadlock detected in the system!\n");
    else
        printf("No deadlock detected.\n");
    return 0;
}

#include <stdio.h>

struct Process {
    int id;
    int burstTime;
    int priority; // Lower number = higher priority
    int waitingTime;
};

void simulateAging(struct Process p[], int n) {
    printf("Simulating Priority Scheduling with Aging:\n");
    int time = 0;
    int completed = 0;

    while (completed < n) {
        // Find process with highest priority (lowest priority number)
        int idx = -1;
        int highestPriority = 9999;

        for (int i = 0; i < n; i++) {
            if (p[i].burstTime > 0 && p[i].priority < highestPriority) {
                highestPriority = p[i].priority;
                idx = i;
            }
        }

        if (idx != -1) {
            printf("Time %d: Executing Process P%d (Priority: %d)\n", time, p[idx].id, p[idx].priority);
            p[idx].burstTime--;
            time++;

            if (p[idx].burstTime == 0) {
                completed++;
            }

            // Aging: increase priority (decrease priority value) for all other waiting processes
            for (int i = 0; i < n; i++) {
                if (i != idx && p[i].burstTime > 0) {
                    p[i].waitingTime++;
                    if (p[i].waitingTime % 3 == 0 && p[i].priority > 0) {
                        p[i].priority--; // Boost priority due to waiting
                        printf("  -> Aging boost: P%d priority increased to %d\n", p[i].id, p[i].priority);
                    }
                }
            }
        }
    }
}

int main() {
    struct Process p[] = {{1, 4, 3, 0}, {2, 2, 1, 0}, {3, 3, 2, 0}};
    simulateAging(p, 3);
    return 0;
}

