void compactMemory(int memory[], int *size) {
    int writeIndex = 0;
    // Shift all active (non-zero) process blocks to the beginning
    for (int i = 0; i < *size; i++) {
        if (memory[i] != 0) {
            memory[writeIndex] = memory[i];
            if (i != writeIndex) {
                memory[i] = 0; // Clear old position
            }
            writeIndex++;
        }
