int main() {
    double tlb_access = 20.0;     // nanoseconds
    double memory_access = 100.0; // nanoseconds
    double hit_ratio = 0.85;      // 85% hit rate

    // On hit: TLB lookup + Memory access
    // On miss: TLB lookup + Page table access in RAM + Data memory access
    double eat = (hit_ratio * (tlb_access + memory_access)) + 
