#define MAX_PAGES 64   // max distinct pages a process can touch
#define WINDOW 10       // size of the working‑set window (number of accesses)

int main() {
    int accesses[WINDOW] = {0};   // circular buffer of recent page numbers
    bool in_ws[MAX_PAGES] = {false}; // working‑set bitmap
    int idx = 0; // current position in circular buffer
    int page;
    printf("Enter page numbers (negative to stop):\n");
    while (scanf("%d", &page) == 1 && page >= 0) {
        // remove oldest page from window
        int old = accesses[idx];
        accesses[idx] = page; // insert new page
        // update bitmap
        // decrement count of old page occurrences
        bool still_present = false;
        for (int i = 0; i < WINDOW; ++i) {
            if (i != idx && accesses[i] == old) { still_present = true; break; }
        }
        if (!still_present) in_ws[old] = false; // old page left WS
        in_ws[page] = true; // new page enters WS
        idx = (idx + 1) % WINDOW;
        // display current working set
        printf("Current Working Set: ");
        for (int p = 0; p < MAX_PAGES; ++p) if (in_ws[p]) printf("%d ", p);
        printf("\n");
    }
    return 0;
}
// Important lines: the circular buffer maintains the sliding window; the bitmap `in_ws` holds the current working set.

