        }
    }
    printf("FIFO Page Faults: %d\n", faults);
    return 0;
}

#include <stdio.h>

int predict(int referenceString[], int frames[], int nr, int index, int nf) {
    int farthest = index, res = -1;
    for (int i = 0; i < nf; i++) {
        int j;
        for (j = index; j < nr; j++) {
            if (frames[i] == referenceString[j]) {
                if (j > farthest) {
                    farthest = j;
                    res = i;
                }
                break;
            }
        }
        // If a page is never referenced again in future
        if (j == nr) return i;
    }
    return (res == -1) ? 0 : res;
}

int main() {
    int ref[] = {7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2};
    int n = 13, nf = 3, frames[3] = {-1, -1, -1}, faults = 0;
    for (int i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < nf; j++) if (frames[j] == ref[i]) found = 1;
        if (!found) {
            int pos = (i < nf) ? i : predict(ref, frames, n, i + 1, nf);
            frames[pos] = ref[i];
            faults++;
        }
    }
    printf("Total Page Faults (Optimal): %d\n", faults); // Expected output: 9
    return 0;
}

#include <stdio.h>

int findLRU(int time[], int n) {
    int minimum = time[0], pos = 0;
    for (int i = 1; i < n; ++i) {
        if (time[i] < minimum) {
            minimum = time[i];
            pos = i;
        }
    }
    return pos;
}

int main() {
    int nf = 3, nr = 7;
    int ref[] = {1, 2, 3, 4, 1, 2, 5};
    int frames[3] = {-1, -1, -1}, time[3] = {0}, counter = 0, faults = 0;
    for (int i = 0; i < nr; ++i) {
        int found = 0;
        for (int j = 0; j < nf; ++j) {
            if (frames[j] == ref[i]) {
                counter++;
                time[j] = counter;
                found = 1;
                break;
            }
        }
        if (!found) {
            int pos = (i < nf) ? i : findLRU(time, nf);
            frames[pos] = ref[i];
            counter++;
            time[pos] = counter;
            faults++;
        }
    }
    printf("Total Page Faults (LRU): %d\n", faults); // Expected output: 6
    return 0;
}

#include <stdio.h>

// Conceptual simulation of Page-Fault Frequency (PFF) to prevent thrashing
void checkThrashing(float pageFaultRate, int *allocatedFrames) {
    float upperLimit = 0.50; // 50% threshold
    float lowerLimit = 0.10; // 10% threshold

    if (pageFaultRate > upperLimit) {
        printf("Thrashing warning! PFR: %.2f. Increasing frames / suspending process.\n", pageFaultRate);
        if (*allocatedFrames > 2) (*allocatedFrames)--;
    } else if (pageFaultRate < lowerLimit) {
        printf("Low page fault rate (%.2f). Frames can be reclaimed.\n", pageFaultRate);
    } else {
        printf("System stable. Page fault rate: %.2f\n", pageFaultRate);
    }
}

int main() {
    int frames = 5;
    checkThrashing(0.65, &frames);
    checkThrashing(0.05, &frames);
    return 0;
}

