#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#define BUF_SIZE 5

int buffer[BUF_SIZE];
int in = 0, out = 0;

sem_t empty; // counts free slots
sem_t full;  // counts filled slots
pthread_mutex_t mtx;

void *producer(void *arg) {
    int id = *(int *)arg;
    for (int i = 0; i < 10; ++i) {
        int item = id * 100 + i;               // produce a unique item
        sem_wait(&empty);                      // wait for free slot
        pthread_mutex_lock(&mtx);
        buffer[in] = item;                     // critical section
        printf("Producer %d produced %d at %d\n", id, item, in);
        in = (in + 1) % BUF_SIZE;
        pthread_mutex_unlock(&mtx);
        sem_post(&full);                       // signal a new item
        usleep(100000); // simulate work
    }
    return NULL;
}

void *consumer(void *arg) {
    int id = *(int *)arg;
    for (int i = 0; i < 10; ++i) {
        sem_wait(&full);                       // wait for an item
        pthread_mutex_lock(&mtx);
        int item = buffer[out];                // critical section
        printf("Consumer %d consumed %d from %d\n", id, item, out);
        out = (out + 1) % BUF_SIZE;
        pthread_mutex_unlock(&mtx);
        sem_post(&empty);                      // free a slot
        usleep(150000); // simulate work
    }
    return NULL;
}

int main() {
    pthread_t prod[2], cons[2];
    int ids[2] = {1, 2};
    sem_init(&empty, 0, BUF_SIZE); // all slots free
    sem_init(&full, 0, 0);          // no items yet
    pthread_mutex_init(&mtx, NULL);

    for (int i = 0; i < 2; ++i) {
        pthread_create(&prod[i], NULL, producer, &ids[i]);
        pthread_create(&cons[i], NULL, consumer, &ids[i]);
    }
    for (int i = 0; i < 2; ++i) {
        pthread_join(prod[i], NULL);
        pthread_join(cons[i], NULL);
    }
    sem_destroy(&empty);
    sem_destroy(&full);
    pthread_mutex_destroy(&mtx);
    return 0;
}

