#include <stdio.h>

int main() {
    int n = 2, quantum = 2;
    int bt[] = {5, 4}, rem_bt[] = {5, 4}, wt[] = {0, 0};
    int t = 0, completed = 0;

    while (completed < n) {
        int done = 1;
        for (int i = 0; i < n; i++) {
            if (rem_bt[i] > 0) {
                done = 0;
                if (rem_bt[i] > quantum) {
                    t += quantum;
                    rem_bt[i] -= quantum;
                } else {
                    t += rem_bt[i];
                    wt[i] = t - bt[i];
                    rem_bt[i] = 0;
                    completed++;
                }
            }
        }
        if (done == 1) break;
    }
    printf(
        "Process 0 WT: %d, Process 1 WT: %d\n", wt[0], wt[1]);
    return 0;
}

