#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define N 5

pthread_mutex_t chopsticks[N];

void* philosopher(void* num) {
    int id = *(int*)num;
    int left = id;
    int right = (id + 1) % N;

    // Resource hierarchy: pick lower index first
    int first = (left < right) ? left : right;
    int second = (left > right) ? left : right;

    while(1) {
        printf("Philosopher %d is thinking.\n", id);
        sleep(1);

        pthread_mutex_lock(&chopsticks[first]);
        pthread_mutex_lock(&chopsticks[second]);

        printf("Philosopher %d is eating.\n", id);
        sleep(1);

        pthread_mutex_unlock(&chopsticks[second]);
        pthread_mutex_unlock(&chopsticks[first]);
    }
}

int main() {
    pthread_t thread[N];
    int ids[N];
    for(int i=0; i<N; i++) pthread_mutex_init(&chopsticks[i], NULL);
    for(int i=0; i<N; i++) { ids[i] = i; pthread_create(&thread[i], NULL, philosopher, &ids[i]); }
    for(int i=0; i<N; i++) pthread_join(thread[i], NULL);
    return 0;
}

